## Code Example
```javascript
// Pseudo
class BIT {
  constructor(size) {
    this.tree = new Array(size + 1).fill(0);
  }

  update(idx, delta) {
    while (idx <= this.size) {
      this.tree[idx] += delta;
      idx += idx & -idx;
    }
  }

  query(k) {
    // Binary lift for k-th smallest
    let idx = 0;
    for (let i = Math.pow(2, Math.floor(Math.log2(this.size))); i > 0; i >>= 1) {
      if (idx + i <= this.size && this.tree[idx + i] < k) {
        k -= this.tree[idx + i];
        idx += i;
      }
    }
    return idx + 1;
  }
}
```

